package org.telegram.messenger.tetogram;
import java.util.*;
import java.util.function.ToIntFunction;
public final class AppearanceContrast {
    private AppearanceContrast(){}
    private static final String[][] PAIRS={{"list.windowBackgroundWhite","list.chats_name"},{"list.windowBackgroundWhite","list.chats_message"},{"list.actionBarDefault","list.actionBarDefaultTitle"},{"list.actionBarDefault","list.actionBarDefaultIcon"},{"list.chats_unreadCounter","list.chats_unreadCounterText"},{"windowBackgroundWhite","windowBackgroundWhiteBlackText"},{"windowBackgroundWhite","chats_name"},{"chat_inBubble","chat_messageTextIn"},{"chat_outBubble","chat_messageTextOut"},{"actionBarDefault","actionBarDefaultTitle"},{"actionBarDefault","actionBarDefaultIcon"},{"chat_messagePanelBackground","chat_messagePanelText"},{"chats_unreadCounter","chats_unreadCounterText"},{"section.background","section.text"},{"section.activeBackground","section.activeText"},{"section.badge","section.badgeText"}};
    public static String nativeKey(String key){if(key.startsWith("list."))return key.substring(5);switch(key){case "section.background":return "dialogBackground";case "section.activeBackground":return "chats_actionBackground";case "section.text":return "dialogTextBlack";case "section.activeText":return "chats_actionIcon";case "section.badge":return "chats_unreadCounter";case "section.badgeText":return "chats_unreadCounterText";default:return key;}}
    private static int color(AppearanceConfig.Resolved r,boolean dark,String key,ToIntFunction<String> base){Integer c=r.color(dark,key);return c==null?base.applyAsInt(nativeKey(key)):c;}
    public static List<String> issues(AppearanceConfig.Style draft,AppearanceConfig.Resolved r,boolean dark,ToIntFunction<String> base){ArrayList<String> out=new ArrayList<>();String prefix=dark?"dark.":"light.";int canvas=color(r,dark,"chat_wallpaper",base);for(String[] pair:PAIRS){if(!draft.values.containsKey(prefix+pair[0])&&!draft.values.containsKey(prefix+pair[1]))continue;double threshold=pair[1].endsWith("actionBarDefaultIcon")||pair[1].startsWith("section.")&&!pair[1].equals("section.badgeText")?3:4.5;if(AppearanceColors.visibleRatio(color(r,dark,pair[1],base),color(r,dark,pair[0],base),pair[0].startsWith("list.")?color(r,dark,"list.chat_wallpaper",base):canvas)+.001<threshold)out.add(pair[1]);}return out;}
    public static void repair(AppearanceConfig.Style draft,AppearanceConfig.Resolved r,boolean dark,ToIntFunction<String> base){Set<String> invalid=new HashSet<>(issues(draft,r,dark,base));int canvas=color(r,dark,"chat_wallpaper",base);for(String[] pair:PAIRS)if(invalid.contains(pair[1]))draft.color(dark,pair[1],AppearancePresets.contrast(AppearanceColors.composite(color(r,dark,pair[0],base),pair[0].startsWith("list.")?color(r,dark,"list.chat_wallpaper",base):canvas)));}
}
